const row = $input.first().json;

const startDateMs = new Date(
  "2026-06-01T00:00:00-03:00"
).getTime();

const lastSuccessAt = row.last_success_at ?? '2026-06-01T00:00:00.000';

function dateBrasilToMs(value) {
  const text = String(value).replace(' ', 'T');

  // Se já vier com fuso, usa direto
  if (text.endsWith('Z') || /[+-]\d{2}:\d{2}$/.test(text)) {
    return new Date(text).getTime();
  }

  // Se vier sem fuso, assume Brasil UTC-3
  return new Date(`${text}-03:00`).getTime();
}

function formatBrasilDate(date) {
  return new Intl.DateTimeFormat('en-CA', {
    timeZone: 'America/Sao_Paulo',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).format(date);
}

const lastSuccessMs = dateBrasilToMs(lastSuccessAt);

// Instante atual real
const nowMs = Date.now();
const now = new Date(nowMs);

// Data atual no Brasil
const [yearBrasil, monthBrasil] = formatBrasilDate(now)
  .split('-')
  .map(Number);

// Início do mês atual no Brasil: 01/MM/AAAA 00:00 UTC-3
const monthStartMs = new Date(
  `${yearBrasil}-${String(monthBrasil).padStart(2, '0')}-01T00:00:00.000-03:00`
).getTime();

// Calcula próximo mês
let nextMonth = monthBrasil + 1;
let nextYear = yearBrasil;

if (nextMonth === 13) {
  nextMonth = 1;
  nextYear += 1;
}

// Início do próximo mês no Brasil: 01/MM/AAAA 00:00 UTC-3
const nextMonthStartMs = new Date(
  `${nextYear}-${String(nextMonth).padStart(2, '0')}-01T00:00:00.000-03:00`
).getTime();

// Apenas para visualizar no horário do Brasil
const nowBrasil = new Date(nowMs - 3 * 60 * 60 * 1000)
  .toISOString()
  .replace('T', ' ')
  .replace('Z', '');

return [
  {
    json: {
      after: null,

      lastSuccessAt,
      lastSuccessMs,

      startDateMs,

      nowMs,
      nowBrasil,

      monthStartMs,
      nextMonthStartMs,

      // Campos de conferência
      monthStartBrasil: `${yearBrasil}-${String(monthBrasil).padStart(2, '0')}-01 00:00:00`,
      nextMonthStartBrasil: `${nextYear}-${String(nextMonth).padStart(2, '0')}-01 00:00:00`,

      monthStartIsoUtc: new Date(monthStartMs).toISOString(),
      nextMonthStartIsoUtc: new Date(nextMonthStartMs).toISOString()
    }
  }
];

