function toPostgresDate(value) {
  if (value === undefined || value === null || value === '') {
    return null;
  }

  const s = String(value).trim();

  // Timestamp em milissegundos
  if (/^\d+$/.test(s)) {
    return new Date(Number(s)).toISOString();
  }

  const d = new Date(s);

  if (isNaN(d.getTime())) {
    return null;
  }

  return d.toISOString();
}

const output = [];

const inputItems = $input.all();

for (const item of inputItems) {
  const response = item.json.body ?? item.json;
  const results = response.results ?? [];

  for (const contact of results) {
    const p = contact.properties ?? {};

    const firstname = p.firstname ?? '';
    const lastname = p.lastname ?? '';

    const nome = `${firstname} ${lastname}`
      .replace(/\s+/g, ' ')
      .trim();

    output.push({
      json: {
        hs_object_id: String(p.hs_object_id ?? contact.id),

        nome: nome || null,

        phone: p.phone ?? null,
        mobilephone: p.mobilephone ?? null,

        qualificacao: p.qualificacao ?? null,
        origem: p.origem_ ?? null,

        proprietario_contato: p.hubspot_owner_id ?? null,

        hubspot_owner_assigneddate: toPostgresDate(p.hubspot_owner_assigneddate),
        lastmodifieddate: toPostgresDate(p.lastmodifieddate)
      }
    });
  }
}

return output;

const nowBrasil = new Date(Date.now() - 3 * 60 * 60 * 1000)
  .toISOString()
  .replace('T', ' ')
  .replace('Z', '');

return [
  {
    json: {
      nowIso: nowBrasil
    }
  }
];

const requiredFields = [
  "startDateMs",
  "lastSuccessMs",
  "nowMs"
];

for (const field of requiredFields) {
  if ($json[field] === undefined || $json[field] === null) {
    throw new Error(`Campo obrigatório ausente: ${field}`);
  }
}

return $input.all();

