={{
  JSON.stringify({
    limit: 200,
    after: $json.after || undefined,
    properties: [
      "hs_object_id",
      "firstname",
      "lastname",
      "phone",
      "mobilephone",
      "qualificacao",
      "origem_",
      "hubspot_owner_id",
      "hubspot_owner_assigneddate",
      "lastmodifieddate"
    ],
    filterGroups: [
      {
        filters: [
          {
            propertyName: "hubspot_owner_assigneddate",
            operator: "GTE",
            value: String($json.startDateMs)
          },
          {
            propertyName: "lastmodifieddate",
            operator: "GTE",
            value: String($json.lastSuccessMs)
          },
          {
            propertyName: "lastmodifieddate",
            operator: "LTE",
            value: String($json.nowMs)
          }
        ]
      }
    ]
  })
}}

